function validate([nums, k]) {
  if (nums.length < 2 || nums.length > 1000) return 'nums needs 2 to 1000 values.';
  if (nums.some(v => v < 1 || v > 10000000)) return 'Each value is between 1 and 10^7.';
  if (k < 1 || k > 1000) return 'k is between 1 and 1000.';
  return null;
}

