function maximumLength(nums, k) {
  const dp = Array.from({ length: k }, () => new Array(k).fill(0));
  let best = 0;

  for (const num of nums) {
    const last = num % k;
    for (let prev = 0; prev < k; prev++) {
      dp[last][prev] = dp[prev][last] + 1;
      best = Math.max(best, dp[last][prev]);
    }
  }
  return best;
}

