function maximumLength(nums, k) {
  // For every pair-sum remainder, find the longest chain of indices whose neighbours add up to it.
  const n = nums.length;
  let best = 1;
  for (let target = 0; target < k; target++) {
    const chain = new Array(n).fill(1);
    for (let i = 0; i < n; i++)
      for (let j = 0; j < i; j++)
        if ((nums[j] + nums[i]) % k === target) chain[i] = Math.max(chain[i], chain[j] + 1);
    best = Math.max(best, ...chain);
  }
  return best;
}

