function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 1000 : 2 + Math.floor(rand() * 9);
  const k = large ? 1 + Math.floor(rand() * 1000) : 1 + Math.floor(rand() * 12);
  const high = large ? 10000000 : 30;
  // Most values share a few "hot" remainders, so long alternating subsequences exist.
  const hot = Array.from({ length: 1 + Math.floor(rand() * 4) }, () => Math.floor(rand() * k));
  const nums = Array.from({ length: n }, () => {
    const residue = rand() < 0.75 ? hot[Math.floor(rand() * hot.length)] : Math.floor(rand() * k);
    const low = residue === 0 ? 1 : 0, top = Math.floor((high - residue) / k);
    return residue + k * (low + Math.floor(rand() * (top - low + 1)));
  });
  return [nums, k];
}
